# WHAT: A metaclass is the "class of a class." It controls how classes are created.
# type is the default metaclass. When you write class Foo: ..., Python calls type("Foo", bases, attrs)

class ValidatedMeta(type):
    """Metaclass that ensures all methods have docstrings."""
    def __new__(mcs, name, bases, namespace):
        for key, value in namespace.items():
            if callable(value) and not key.startswith("_") and not value.__doc__:
                raise TypeError(f"Method '{key}' in {name} must have a docstring")
        return super().__new__(mcs, name, bases, namespace)

class MyService(metaclass=ValidatedMeta):
    def process(self):
        """Process data."""  # Docstring required by metaclass!
        pass
