```python name=advanced/typing_advanced.py
from typing import (
    Protocol, TypeVar, Generic, TypeAlias, 
    TypeGuard, Literal, overload, runtime_checkable
)

# --- Protocol (Structural Typing / Interfaces) ---
@runtime_checkable
class Drawable(Protocol):
    def draw(self) -> None: ...

class Circle:
    def draw(self): print("Drawing circle")

print(isinstance(Circle(), Drawable))  # True! (structural check)

# --- TypeVar and Generic ---
T = TypeVar("T")
K = TypeVar("K")
V = TypeVar("V")

class Stack(Generic[T]):
    def __init__(self):
        self._items: list[T] = []
    def push(self, item: T): self._items.append(item)
    def pop(self) -> T: return self._items.pop()

int_stack: Stack[int] = Stack()
int_stack.push(42)

# --- TypeAlias ---
JSON: TypeAlias = dict[str, "JSON"] | list["JSON"] | str | int | float | bool | None

# --- Literal ---
def set_mode(mode: Literal["read", "write", "append"]) -> None: ...

# --- Overload ---
@overload
def process(data: str) -> str: ...
@overload
def process(data: int) -> int: ...
def process(data):
    if isinstance(data, str): return data.upper()
    return data * 2

# --- TypeGuard ---
def is_string_list(val: list) -> TypeGuard[list[str]]:
    return all(isinstance(x, str) for x in val)
